options.styles:
:root{--fs-accent:#00c8ff;--fs-alert:#ff5a5a;--fs-text:#eef4f8;--fs-dim:#8fa3b3;--fs-mono:ui-monospace,"JetBrains Mono",Menlo,Consolas,monospace;}
.fs-banner{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;font-family:var(--fs-mono);color:var(--fs-dim);padding:6px 4px;}
.fs-banner-left{display:flex;align-items:center;gap:12px;font-size:12px;letter-spacing:.04em;}.fs-banner-right{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.fs-prompt{color:var(--fs-accent);}.fs-path{color:var(--fs-text);margin-left:6px;}.fs-sep{opacity:.35;}.fs-title{color:var(--fs-text);font-weight:700;letter-spacing:.14em;font-size:13px;}.fs-thin{font-weight:400;color:var(--fs-dim);}
.fs-pill{display:inline-flex;align-items:center;gap:8px;padding:5px 12px;border:1px solid rgba(255,255,255,.16);border-radius:999px;color:var(--fs-text);font-family:var(--fs-mono);font-size:11px;letter-spacing:.12em;text-decoration:none;background:rgba(8,12,18,.6);}
.fs-pill--alert{border-color:rgba(255,90,90,.45);background:rgba(255,90,90,.12);}.fs-pill--link:hover{border-color:var(--fs-accent);}
.fs-dot{width:7px;height:7px;border-radius:50%;background:var(--fs-alert);animation:fs-pulse 1.8s ease-out infinite;}@keyframes fs-pulse{0%{box-shadow:0 0 0 0 rgba(255,90,90,.55)}100%{box-shadow:0 0 0 9px rgba(255,90,90,0)}}

.fs-wrap{font-family:ui-monospace,"JetBrains Mono",Menlo,Consolas,monospace;font-size:12px;color:#cfd8e3;}
.fs-tab{width:100%;border-collapse:collapse;}
.fs-tab th{text-align:left;color:#8fa3b3;font-weight:600;letter-spacing:.08em;font-size:11px;padding:6px 8px;border-bottom:1px solid rgba(255,255,255,.12);}
.fs-tab td{padding:5px 8px;border-bottom:1px solid rgba(255,255,255,.06);white-space:nowrap;}
.fs-tab tr:hover td{background:rgba(0,200,255,.05);}
.fs-cpe{color:#00c8ff;}.fs-c2{color:#ff5a5a;}.fs-num{text-align:right;}.fs-dim{color:#8fa3b3;}.fs-act{text-align:right;}
.fs-btn{font-family:inherit;font-size:11px;letter-spacing:.06em;padding:4px 10px;border-radius:5px;border:1px solid rgba(0,200,255,.4);background:rgba(0,200,255,.12);color:#eef4f8;cursor:pointer;margin-left:6px;}
.fs-btn:hover{background:rgba(0,200,255,.28);}
.fs-btn--warn{border-color:rgba(255,90,90,.45);background:rgba(255,90,90,.12);}.fs-btn--warn:hover{background:rgba(255,90,90,.3);}
.fs-btn--ok{border-color:rgba(155,225,93,.45);background:rgba(155,225,93,.14);}.fs-btn--ok:hover{background:rgba(155,225,93,.3);}
.fs-btn:disabled{opacity:.5;cursor:wait;}
.fs-form{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;padding:8px 8px 12px;margin-bottom:8px;border:1px solid rgba(255,255,255,.1);border-radius:8px;background:rgba(8,12,18,.5);}
.fs-form-title{width:100%;color:#9be15d;font-size:11px;letter-spacing:.14em;}
.fs-form label{display:flex;flex-direction:column;gap:4px;color:#8fa3b3;font-size:11px;}
.fs-form input,.fs-form select{font-family:inherit;font-size:12px;padding:5px 8px;border-radius:5px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.05);color:#eef4f8;min-width:150px;}
.fs-msg{margin-top:8px;min-height:16px;font-size:11px;}
.fs-msg.ok{color:#9be15d;}.fs-msg.err{color:#ff5a5a;}

options.afterRender:
(function(){
  var root=(typeof context!=='undefined'&&context.element)?context.element:document;
  var wrap=root.querySelector('.fs-wrap'); if(!wrap||wrap.dataset.fsBound) return; wrap.dataset.fsBound='1';
  var API=wrap.dataset.api, TOKEN=wrap.dataset.token, msg=root.querySelector('#fs-msg');
  function say(t,ok){ if(msg){msg.textContent=t; msg.className='fs-msg '+(ok?'ok':'err');} }
  function refresh(){ try{ if(typeof context!=='undefined'&&context.grafana&&context.grafana.refresh) context.grafana.refresh(); }catch(e){} }
  function post(path,body,btn){
    if(btn) btn.disabled=true;
    return fetch(API+path,{method:'POST',headers:{'Content-Type':'application/json','X-Token':TOKEN},body:JSON.stringify(body)})
      .then(function(r){return r.json().then(function(j){return {ok:r.ok,j:j};});})
      .then(function(x){ if(x.ok){say('OK: '+JSON.stringify(x.j),true); setTimeout(refresh,600);} else say('Erro: '+(x.j.erro||JSON.stringify(x.j)),false); })
      .catch(function(e){ say('Falha de rede: '+e,false); })
      .finally(function(){ if(btn) btn.disabled=false; });
  }
  wrap.addEventListener('click',function(e){
    var b=e.target.closest&&e.target.closest('button[data-acao]'); if(!b) return;
    e.preventDefault();
    var a=b.dataset.acao;
    if(a==='remover'){ if(!confirm('Liberar '+(b.dataset.escopo==='destino'?'o C2 inteiro':'este fluxo')+' de '+b.dataset.chave+' ?')) return;
      post('/rules/remove',{chave:b.dataset.chave,escopo:b.dataset.escopo,motivo:'liberado pelo operador',dias:7},b); }
    else if(a==='wl-add'){ var g=function(id){var el=root.querySelector('#'+id);return el?el.value.trim():'';};
      if(!g('wl-cidr')){say('Informe o IP/CIDR',false);return;}
      post('/whitelist/add',{cidr:g('wl-cidr'),porta:g('wl-porta'),proto:g('wl-proto'),motivo:g('wl-motivo'),dias:g('wl-dias')||'0'},b); }
    else if(a==='wl-del'){ if(!confirm('Remover a entrada da whitelist?')) return; post('/whitelist/remove',{id:b.dataset.id},b); }
  });
})();

